import { describe, it, expect } from "vitest";
import { scoreArmy } from "./sphinx-score.js";

describe("Sphinx scoring", () => {
  it("scores an army with no Sphinx as 0 — Chimera, Orthrus, Zombie → 0", () => {
    expect(
      scoreArmy([
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
      ]),
    ).toBe(0);
  });
  it("scores a lone Sphinx with one other type as 2 (1 base + 1 else) — Sphinx, Cyclops → 2", () => {
    expect(
      scoreArmy([{ monster: "sphinx" }, { monster: "cyclops" }]),
    ).toBe(2);
  });
  it("scores a Sphinx seeing three-or-fewer other types as 2 (1 base + 1 else) — Sphinx, Chimera, Orthrus → 2", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
      ]),
    ).toBe(2);
  });
  it("does not count a Sphinx's own type, so four other types score 3 (1 base + 2 per type beyond three) — Sphinx, Chimera, Orthrus, Zombie, Hydra → 3", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
        { monster: "hydra" },
      ]),
    ).toBe(3);
  });
  it("scores 2 per type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra, Cyclops → 5", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
        { monster: "hydra" },
        { monster: "cyclops" },
      ]),
    ).toBe(5);
  });
  it.todo(
    "ignores duplicate cards of the same monster when counting types — Sphinx, Chimera, Chimera, Chimera, Orthrus, Orthrus → 2",
  );
  it.todo(
    "counts all Undead Warrior point variants as a single type — Sphinx, Undead Warrior (1), Undead Warrior (3), Chimera → 2",
  );
  it.todo(
    "counts Undead Warrior variants as one type among several monsters — Sphinx, Undead Warrior (1), Undead Warrior (2), Undead Warrior (3), Cyclops, Orthrus, Chimera → 3",
  );
  it.todo(
    "scores each Sphinx, with another Sphinx counting as a type — Sphinx, Sphinx, Chimera, Orthrus → 4",
  );
  it.todo(
    "scores each Sphinx beyond three types when another Sphinx is present — Sphinx, Sphinx, Chimera, Orthrus, Zombie → 6",
  );
});

