export type Monster =
  | "sphinx"
  | "undead-warrior"
  | "zombie"
  | "hydra"
  | "cyclops"
  | "orthrus"
  | "chimera";

export type Card = {
  monster: Monster;
  rank?: number;
};

const isSphinx = (card: Card): boolean => card.monster === "sphinx";

const countTypesBesidesSphinx = (army: Card[]): number =>
  new Set(army.filter((card) => !isSphinx(card)).map((card) => card.monster))
    .size;

// "Sphinx — 1 point. 2 per type beyond three, else 1."
const pointsPerSphinx = (typeCount: number): number =>
  1 + (typeCount > 3 ? 2 * (typeCount - 3) : 1);

export function scoreArmy(army: Card[]): number {
  if (!army.some(isSphinx)) return 0;
  return pointsPerSphinx(countTypesBesidesSphinx(army));
}

